/* The illustrations follow the accent colour of the page (CSS variables, see accents.css).
   Dark neutrals (#052e16, #04130a, #050805) and the laptop greys stay as they are. */
const MAP = {
  '#22c55e': 'var(--ac)',
  '#16a34a': 'var(--acL)',
  '#4ade80': 'var(--ac3)',
  '#86efac': 'var(--ac2)',
  '#15803d': 'var(--ac2L)',
  '#14532d': 'var(--dk)',
  '#0f3d20': 'var(--dk)',
  '#0f2a18': 'var(--dk2)',
  '#dcfce7': 'var(--sk1)',
  '#a7f3d0': 'var(--sk2)',
};
const themed = (s) => s.replace(/fill="(#[0-9a-fA-F]{6})"/g, (m, h) => (MAP[h.toLowerCase()] ? `style="fill:${MAP[h.toLowerCase()]}"` : m));
Object.keys(SVGS).forEach((k) => {
  SVGS[k] = themed(SVGS[k]);
});
